/* ==========================================================
   MediDent Clinic — Prescription System
   All data is stored locally in this browser via localStorage.
   ========================================================== */

const LOGO_DATA_URI = "data:image/png;base64,";

const STORAGE_KEY = "medident_prescriptions_v1";

// Doctor profiles now live in doctors.js (admin-manageable, localStorage-backed).
// See getDoctors() / getDoctorById() there.

const CLINIC = {
  name: "MediDent",
  tagline: "Dr. Gholba's Family Physician & Dental Clinic",
  location: "Pune, Maharashtra"
};

const MED_FORM_OPTIONS = ["Tab", "Cap", "Inj", "Syrup", "Oint", "Eye Drop"];

let selectedDoctorId = (getDoctors()[0] || {}).id || null;
let medRowCount = 0;
let currentRenderedRecord = null; // set when a prescription is shown in the preview view
let currentRecordId = null; // set when viewing/editing an existing saved record

/* ---------------- utilities ---------------- */

function uid() {
  return "rx_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8);
}

function todayISO() {
  const d = new Date();
  return d.toISOString().slice(0, 10);
}

function formatDateDisplay(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return `${d}-${months[parseInt(m,10)-1]}-${y}`;
}

function escapeHtml(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function showToast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => t.classList.remove("show"), 2200);
}

/* ---------------- print settings (letterhead top space) ---------------- */

const SETTINGS_KEY = "medident_settings_v1";
const DEFAULT_LETTERHEAD_TOP_MM = 40;

function getSettings() {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function saveSettings(settings) {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch (e) {
    console.error("Failed to save settings", e);
  }
}

function getLetterheadTopMM() {
  const s = getSettings();
  return (typeof s.letterheadTopMM === "number") ? s.letterheadTopMM : DEFAULT_LETTERHEAD_TOP_MM;
}

function setLetterheadTopMM(mm) {
  const s = getSettings();
  s.letterheadTopMM = mm;
  saveSettings(s);
  applyLetterheadTopMM(mm);
}

function applyLetterheadTopMM(mm) {
  const sheet = document.getElementById("rxSheet");
  if (sheet) sheet.style.setProperty("--letterhead-top", mm + "mm");
}

function getAllRecords() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    console.error("Failed to read prescriptions from storage", e);
    return [];
  }
}

function saveAllRecords(records) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    return true;
  } catch (e) {
    console.error("Failed to save prescriptions", e);
    return false;
  }
}

/* ---------------- doctor selector ---------------- */

// A doctor account only ever sees/uses their own profile here; Admin can
// pick any doctor (e.g. when writing a prescription on someone's behalf).
function visibleDoctorsForCurrentUser() {
  const user = (typeof getCurrentUser === "function") ? getCurrentUser() : null;
  const all = getDoctors();
  if (user && user.role === "doctor" && user.doctorId) {
    return all.filter(d => d.id === user.doctorId);
  }
  return all;
}

function updateVitalsPanelVisibility() {
  const panel = document.getElementById("vitalsPanel");
  if (!panel) return;
  const doc = getDoctorById(selectedDoctorId);
  panel.style.display = (doc && doc.noVitals) ? "none" : "";
}

function renderDoctorSelect() {
  const wrap = document.getElementById("doctorSelect");
  if (!wrap) return;
  wrap.innerHTML = "";
  const list = visibleDoctorsForCurrentUser();
  if (list.length && !list.some(d => d.id === selectedDoctorId)) {
    selectedDoctorId = list[0].id;
  }
  list.forEach(doc => {
    const card = document.createElement("div");
    card.className = "doctor-card" + (doc.id === selectedDoctorId ? " selected" : "");
    card.dataset.docId = doc.id;
    card.innerHTML = `
      <div class="dname">${escapeHtml(doc.name)}</div>
      <div class="dcred">${escapeHtml(doc.credentials)}</div>
      <div class="dreg">${escapeHtml(doc.reg)}</div>
    `;
    card.addEventListener("click", () => {
      selectedDoctorId = doc.id;
      renderDoctorSelect();
    });
    wrap.appendChild(card);
  });
  updateVitalsPanelVisibility();
}

/* ---------------- medicine rows ---------------- */

function parseDosage(dosage) {
  // Accepts "1-0-0" style strings (or already-split parts) and returns {m,a,e}
  if (!dosage) return { m: "", a: "", e: "" };
  const parts = String(dosage).split(/[-–]/).map(p => p.trim());
  return { m: parts[0] || "", a: parts[1] || "", e: parts[2] || "" };
}

function addMedRow(prefill) {
  medRowCount += 1;
  const tbody = document.getElementById("medTableBody");
  const tr = document.createElement("tr");
  tr.dataset.rowId = medRowCount;
  const dose = parseDosage(prefill?.dosage);
  tr.innerHTML = `
    <td class="col-num">${tbody.children.length + 1}</td>
    <td>
      <select class="med-form">
        ${MED_FORM_OPTIONS.map(opt => `<option value="${opt}"${prefill?.form === opt ? " selected" : ""}>${opt}</option>`).join("")}
      </select>
    </td>
    <td><input type="text" class="med-name" placeholder="Start typing to search medicines…" value="${escapeHtml(prefill?.name)}"></td>
    <td><input type="text" class="med-comp" placeholder="e.g. Empagliflozin 12.5mg + Metformin 500mg" value="${escapeHtml(prefill?.comp)}"></td>
    <td>
      <div class="dose-group">
        <div class="dose-cell">
          <span class="dose-label">M</span>
          <input type="text" class="dose-box dose-m" maxlength="3" value="${escapeHtml(dose.m)}">
        </div>
        <div class="dose-cell">
          <span class="dose-label">A</span>
          <input type="text" class="dose-box dose-a" maxlength="3" value="${escapeHtml(dose.a)}">
        </div>
        <div class="dose-cell">
          <span class="dose-label">E</span>
          <input type="text" class="dose-box dose-e" maxlength="3" value="${escapeHtml(dose.e)}">
        </div>
      </div>
    </td>
    <td><input type="text" class="med-timing" placeholder="Before food, daily" value="${escapeHtml(prefill?.timing)}"></td>
    <td><input type="text" class="med-duration" placeholder="100 days" value="${escapeHtml(prefill?.duration)}"></td>
    <td><input type="text" class="med-notes" placeholder="e.g. Drink plenty of water" value="${escapeHtml(prefill?.notes)}"></td>
    <td class="col-remove"><button type="button" class="remove-row-btn" title="Remove medicine">&times;</button></td>
  `;
  tr.querySelector(".remove-row-btn").addEventListener("click", () => {
    tr.remove();
    renumberMedRows();
  });
  tbody.appendChild(tr);
  if (typeof wireMedNameAutofill === "function") {
    wireMedNameAutofill(tr);
  }
}

/* ---------------- additional vitals/examination rows ---------------- */

let vitalRowCount = 0;

function addVitalRow(prefill) {
  vitalRowCount += 1;
  const tbody = document.getElementById("vitalsExtraTableBody");
  const tr = document.createElement("tr");
  tr.innerHTML = `
    <td><input type="text" class="vital-label" placeholder="e.g. HbA1c" value="${escapeHtml(prefill?.label)}"></td>
    <td><input type="text" class="vital-value" placeholder="e.g. 6.7%" value="${escapeHtml(prefill?.value)}"></td>
    <td class="col-remove"><button type="button" class="remove-row-btn" title="Remove">&times;</button></td>
  `;
  tr.querySelector(".remove-row-btn").addEventListener("click", () => tr.remove());
  tbody.appendChild(tr);
}

function clearVitalRows() {
  document.getElementById("vitalsExtraTableBody").innerHTML = "";
  vitalRowCount = 0;
}

function collectVitalRows() {
  const rows = document.querySelectorAll("#vitalsExtraTableBody tr");
  const extras = [];
  rows.forEach(row => {
    const label = row.querySelector(".vital-label").value.trim();
    const value = row.querySelector(".vital-value").value.trim();
    if (label && value) {
      extras.push({ label, value });
    }
  });
  return extras;
}

function renumberMedRows() {
  const rows = document.querySelectorAll("#medTableBody tr");
  rows.forEach((row, i) => {
    row.querySelector(".col-num").textContent = i + 1;
  });
}

function clearMedRows() {
  document.getElementById("medTableBody").innerHTML = "";
  medRowCount = 0;
}

function collectMedRows() {
  const rows = document.querySelectorAll("#medTableBody tr");
  const meds = [];
  rows.forEach(row => {
    const form = row.querySelector(".med-form").value;
    const name = row.querySelector(".med-name").value.trim();
    const comp = row.querySelector(".med-comp").value.trim();
    const doseM = row.querySelector(".dose-m").value.trim();
    const doseA = row.querySelector(".dose-a").value.trim();
    const doseE = row.querySelector(".dose-e").value.trim();
    const dosage = (doseM || doseA || doseE) ? `${doseM || "0"}-${doseA || "0"}-${doseE || "0"}` : "";
    const timing = row.querySelector(".med-timing").value.trim();
    const duration = row.querySelector(".med-duration").value.trim();
    const notes = row.querySelector(".med-notes").value.trim();
    if (name || comp || dosage || timing || duration || notes) {
      meds.push({ form, name, comp, dosage, timing, duration, notes });
    }
  });
  return meds;
}

/* ---------------- form <-> record ---------------- */

function readFormAsRecord() {
  const doctor = getDoctorById(selectedDoctorId) || {};
  return {
    id: currentRecordId || uid(),
    createdAt: currentRecordId ? undefined : new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    doctorId: selectedDoctorId,
    doctorName: doctor.name || "",
    patient: {
      name: document.getElementById("pName").value.trim(),
      age: document.getElementById("pAge").value.trim(),
      gender: document.getElementById("pGender").value,
      phone: document.getElementById("pPhone").value.trim(),
      email: document.getElementById("pEmail").value.trim(),
      date: document.getElementById("pDate").value || todayISO(),
      time: document.getElementById("pTime").value.trim(),
      visitType: document.getElementById("pVisitType").value
    },
    vitals: {
      bp: document.getElementById("vBP").value.trim(),
      pulse: document.getElementById("vPulse").value.trim(),
      weight: document.getElementById("vWeight").value.trim(),
      systemic: document.getElementById("vSystemic").value.trim(),
      extra: collectVitalRows()
    },
    diagnosis: document.getElementById("dDiagnosis").value.trim(),
    quickNotes: document.getElementById("dQuickNotes").value.trim(),
    medicines: collectMedRows(),
    advice: document.getElementById("dAdvice").value.trim(),
    tests: document.getElementById("dTests").value.trim(),
    followup: document.getElementById("dFollowup").value.trim()
  };
}

function loadRecordIntoForm(rec) {
  selectedDoctorId = rec.doctorId || (getDoctors()[0] || {}).id;
  renderDoctorSelect();

  document.getElementById("pName").value = rec.patient?.name || "";
  document.getElementById("pAge").value = rec.patient?.age || "";
  document.getElementById("pGender").value = rec.patient?.gender || "";
  document.getElementById("pPhone").value = rec.patient?.phone || "";
  document.getElementById("pEmail").value = rec.patient?.email || "";
  document.getElementById("pDate").value = rec.patient?.date || todayISO();
  document.getElementById("pTime").value = rec.patient?.time || "";
  document.getElementById("pVisitType").value = rec.patient?.visitType || "Follow-up";

  document.getElementById("vBP").value = rec.vitals?.bp || "";
  document.getElementById("vPulse").value = rec.vitals?.pulse || "";
  document.getElementById("vWeight").value = rec.vitals?.weight || "";
  document.getElementById("vSystemic").value = rec.vitals?.systemic || "";

  clearVitalRows();
  if (rec.vitals?.extra && rec.vitals.extra.length) {
    rec.vitals.extra.forEach(v => addVitalRow(v));
  }

  document.getElementById("dDiagnosis").value = rec.diagnosis || "";
  document.getElementById("dQuickNotes").value = rec.quickNotes || "";
  document.getElementById("dAdvice").value = rec.advice || "";
  document.getElementById("dTests").value = rec.tests || "";
  document.getElementById("dFollowup").value = rec.followup || "";

  clearMedRows();
  if (rec.medicines && rec.medicines.length) {
    rec.medicines.forEach(m => addMedRow({
      form: m.form, name: m.name, comp: m.comp, dosage: m.dosage,
      timing: m.timing, duration: m.duration, notes: m.notes
    }));
  } else {
    addMedRow();
  }

  currentRecordId = rec.id;
}

function resetForm() {
  currentRecordId = null;
  const user = (typeof getCurrentUser === "function") ? getCurrentUser() : null;
  if (user && user.role === "doctor" && user.doctorId) {
    selectedDoctorId = user.doctorId;
  } else {
    selectedDoctorId = (getDoctors()[0] || {}).id || null;
  }
  renderDoctorSelect();
  document.getElementById("pName").value = "";
  document.getElementById("pAge").value = "";
  document.getElementById("pGender").value = "";
  document.getElementById("pPhone").value = "";
  document.getElementById("pEmail").value = "";
  document.getElementById("pDate").value = todayISO();
  document.getElementById("pTime").value = "";
  document.getElementById("pVisitType").value = "Follow-up";
  document.getElementById("vBP").value = "";
  document.getElementById("vPulse").value = "";
  document.getElementById("vWeight").value = "";
  document.getElementById("vSystemic").value = "";
  clearVitalRows();
  document.getElementById("dDiagnosis").value = "";
  document.getElementById("dQuickNotes").value = "";
  document.getElementById("dAdvice").value = "";
  document.getElementById("dTests").value = "";
  document.getElementById("dFollowup").value = "";
  clearMedRows();
  addMedRow();
}

/* ---------------- save ---------------- */

function validateRecord(rec) {
  if (!rec.patient.name) {
    showToast("Please enter the patient's name before saving.");
    return false;
  }
  return true;
}

function persistRecord(rec) {
  const records = getAllRecords();
  const idx = records.findIndex(r => r.id === rec.id);
  if (idx >= 0) {
    rec.createdAt = records[idx].createdAt || rec.updatedAt;
    records[idx] = rec;
  } else {
    rec.createdAt = rec.createdAt || rec.updatedAt;
    records.unshift(rec);
  }
  saveAllRecords(records);
  currentRecordId = rec.id;
  return rec;
}

/* ---------------- rx sheet rendering ---------------- */

function renderRxSheet(rec) {
  currentRenderedRecord = rec;
  const doctor = getDoctorById(rec.doctorId) || getDoctors()[0] || { name: "Unknown Doctor", credentials: "", reg: "", contact: "" };
  const sheet = document.getElementById("rxSheet");
  applyLetterheadTopMM(getLetterheadTopMM());

  const vitalsParts = [];
  if (rec.vitals.bp) vitalsParts.push(`<b>BP</b> ${escapeHtml(rec.vitals.bp)} mmHg`);
  if (rec.vitals.pulse) vitalsParts.push(`<b>Pulse</b> ${escapeHtml(rec.vitals.pulse)}`);
  if (rec.vitals.weight) vitalsParts.push(`<b>Weight</b> ${escapeHtml(rec.vitals.weight)} kg`);
  (rec.vitals.extra || []).forEach(v => {
    vitalsParts.push(`<b>${escapeHtml(v.label)}</b> ${escapeHtml(v.value)}`);
  });

  const medsRows = (rec.medicines || []).map((m, i) => `
    <tr>
      <td style="width:4%;">${i + 1}</td>
      <td style="width:9%;">${escapeHtml(m.form || "")}</td>
      <td style="width:21%;">
        <div class="rx-med-name">${escapeHtml(m.name)}</div>
        ${m.comp ? `<div class="rx-med-comp">${escapeHtml(m.comp)}</div>` : ""}
      </td>
      <td style="width:13%;">${escapeHtml(m.dosage)}</td>
      <td style="width:19%;">${escapeHtml(m.timing)}</td>
      <td style="width:12%;">${escapeHtml(m.duration)}</td>
      <td style="width:22%;">${escapeHtml(m.notes)}</td>
    </tr>
  `).join("");

  sheet.innerHTML = `
    <div class="rx-head print-hide">
      <div class="rx-logo">
        <img src="${LOGO_DATA_URI}" alt="MediDent logo">
      </div>
      <div class="rx-doctor-block">
        <div class="rdname">${escapeHtml(doctor.name)}</div>
        <div>${escapeHtml(doctor.credentials)}</div>
        <div>${escapeHtml(doctor.reg)}</div>
      </div>
    </div>

    <div class="rx-meta print-hide">
      <div>${escapeHtml(CLINIC.tagline)} · ${escapeHtml(CLINIC.location)}</div>
      <div>Ph: ${escapeHtml(doctor.contact)}</div>
    </div>

    <div class="rx-patient-grid">
      <div><span class="k">Patient:</span><span class="v">${escapeHtml(rec.patient.name)}</span></div>
      <div><span class="k">Age / Gender:</span><span class="v">${escapeHtml(rec.patient.age)}${rec.patient.age ? "y" : ""}${rec.patient.gender ? " / " + escapeHtml(rec.patient.gender) : ""}</span></div>
      <div><span class="k">Phone:</span><span class="v">${escapeHtml(rec.patient.phone)}</span></div>
      <div><span class="k">Date:</span><span class="v">${escapeHtml(formatDateDisplay(rec.patient.date))}</span></div>
      <div><span class="k">Time:</span><span class="v">${escapeHtml(rec.patient.time)}</span></div>
      <div><span class="k">Visit:</span><span class="v">${escapeHtml(rec.patient.visitType)}</span></div>
    </div>

    ${vitalsParts.length ? `<div class="rx-vitals">${vitalsParts.join(" &nbsp;·&nbsp; ")}</div>` : ""}
    ${rec.vitals.systemic ? `<div class="rx-vitals" style="margin-top:2px;">${escapeHtml(rec.vitals.systemic)}</div>` : ""}

    ${(rec.diagnosis || rec.quickNotes) ? `
      <div class="rx-section-title">Diagnosis</div>
      ${rec.quickNotes ? `<div class="rx-diagnosis"><i>${escapeHtml(rec.quickNotes)}</i></div>` : ""}
      ${rec.diagnosis ? `<div class="rx-diagnosis">${escapeHtml(rec.diagnosis)}</div>` : ""}
    ` : ""}

    <div class="rx-symbol">℞</div>

    ${medsRows ? `
    <table class="rx-med-table">
      <thead>
        <tr>
          <th>#</th><th>Form</th><th>Medicine</th><th>Dosage</th><th>Timing</th><th>Duration</th><th>Notes</th>
        </tr>
      </thead>
      <tbody>${medsRows}</tbody>
    </table>` : `<div class="rx-notes" style="color:#999;">No medicines added.</div>`}

    ${rec.advice ? `
      <div class="rx-section-title">Advice</div>
      <div class="rx-notes">${escapeHtml(rec.advice)}</div>
    ` : ""}

    <div style="display:flex; gap:24px; margin-top:8px;">
      ${rec.tests ? `<div style="font-size:12px;"><b>Tests prescribed:</b> ${escapeHtml(rec.tests)}</div>` : ""}
      ${rec.followup ? `<div style="font-size:12px;"><b>Follow-up:</b> ${escapeHtml(formatDateDisplay(rec.followup))}</div>` : ""}
    </div>

    <div class="rx-sign-area">
      <div class="rx-stamp-box">
        <div class="stamp-space"></div>
        <div class="stamp-label">Clinic stamp</div>
        <div class="rx-sign-line">
          <div class="sname">${escapeHtml(doctor.name)}</div>
          <div class="sreg">${escapeHtml(doctor.credentials)}</div>
          <div class="sreg">${escapeHtml(doctor.reg)}</div>
        </div>
      </div>
    </div>

    <div class="rx-bottom-strip print-hide">
      ${escapeHtml(CLINIC.tagline)} &nbsp;·&nbsp; ${escapeHtml(CLINIC.location)} &nbsp;·&nbsp; This is a computer-generated prescription.
    </div>
  `;
}

/* ---------------- history view ---------------- */

function renderHistory(filter) {
  const list = document.getElementById("historyList");
  const user = (typeof getCurrentUser === "function") ? getCurrentUser() : null;
  let records = getAllRecords();

  // A doctor only ever sees their own patients here — never another doctor's.
  if (user && user.role === "doctor" && user.doctorId) {
    records = records.filter(r => r.doctorId === user.doctorId);
  }

  const q = (filter || "").trim().toLowerCase();

  const filtered = records.filter(r => {
    if (!q) return true;
    const name = (r.patient?.name || "").toLowerCase();
    const phone = (r.patient?.phone || "").toLowerCase();
    return name.includes(q) || phone.includes(q);
  });

  if (!filtered.length) {
    list.innerHTML = `
      <div class="empty-state">
        <div>${records.length ? "No matching prescriptions found." : "No prescriptions saved yet. Create one from the New Prescription tab."}</div>
      </div>
    `;
    return;
  }

  list.innerHTML = "";
  filtered.forEach(rec => {
    const doctor = getDoctorById(rec.doctorId) || getDoctors()[0] || { name: "Unknown Doctor" };
    const medsSummary = (rec.medicines || []).map(m => m.name).filter(Boolean).join(", ");
    const item = document.createElement("div");
    item.className = "history-item";
    item.innerHTML = `
      <div class="hi-main">
        <div class="hi-name">${escapeHtml(rec.patient.name || "Unnamed patient")}</div>
        <div class="hi-meta">${escapeHtml(formatDateDisplay(rec.patient.date))} ${rec.patient.time ? "· " + escapeHtml(rec.patient.time) : ""} · ${escapeHtml(doctor.name)} ${rec.patient.phone ? "· " + escapeHtml(rec.patient.phone) : ""}</div>
        ${medsSummary ? `<div class="hi-meds">${escapeHtml(medsSummary)}</div>` : ""}
      </div>
      <div class="hi-actions">
        <button class="btn secondary view-btn" type="button">View / Print</button>
        <button class="btn ghost edit-btn" type="button">Edit</button>
        <button class="btn danger delete-btn" type="button">Delete</button>
      </div>
    `;
    item.querySelector(".view-btn").addEventListener("click", () => {
      currentRecordId = rec.id;
      renderRxSheet(rec);
      switchView("preview");
    });
    item.querySelector(".edit-btn").addEventListener("click", () => {
      loadRecordIntoForm(rec);
      switchView("new");
    });
    item.querySelector(".delete-btn").addEventListener("click", () => {
      if (confirm(`Delete the prescription for ${rec.patient.name || "this patient"} dated ${formatDateDisplay(rec.patient.date)}? This cannot be undone.`)) {
        const remaining = getAllRecords().filter(r => r.id !== rec.id);
        saveAllRecords(remaining);
        renderHistory(document.getElementById("historySearch").value);
        showToast("Prescription deleted.");
      }
    });
    list.appendChild(item);
  });
}

/* ---------------- view switching ---------------- */

function switchView(name) {
  document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
  document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));

  if (name === "new") {
    document.getElementById("view-new").classList.add("active");
    document.querySelector('.tab-btn[data-view="new"]').classList.add("active");
  } else if (name === "history") {
    document.getElementById("view-history").classList.add("active");
    document.querySelector('.tab-btn[data-view="history"]').classList.add("active");
    renderHistory(document.getElementById("historySearch").value);
  } else if (name === "admin") {
    document.getElementById("view-admin").classList.add("active");
    document.querySelector('.tab-btn[data-view="admin"]').classList.add("active");
  } else if (name === "preview") {
    document.getElementById("view-preview").classList.add("active");
  }
}

/* ---------------- event wiring ---------------- */

function wireEvents() {
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => switchView(btn.dataset.view));
  });

  document.getElementById("addMedRow").addEventListener("click", () => addMedRow());
  document.getElementById("addVitalRow").addEventListener("click", () => addVitalRow());

  document.getElementById("clearFormBtn").addEventListener("click", () => {
    if (confirm("Clear the form? Unsaved changes will be lost.")) {
      resetForm();
      showToast("Form cleared.");
    }
  });

  document.getElementById("saveOnlyBtn").addEventListener("click", () => {
    const rec = readFormAsRecord();
    if (!validateRecord(rec)) return;
    persistRecord(rec);
    showToast("Saved to patient history.");
    if (typeof maybeAutoEmail === "function") maybeAutoEmail(rec);
  });

  document.getElementById("saveAndPreviewBtn").addEventListener("click", () => {
    const rec = readFormAsRecord();
    if (!validateRecord(rec)) return;
    persistRecord(rec);
    renderRxSheet(rec);
    switchView("preview");
    if (typeof maybeAutoEmail === "function") maybeAutoEmail(rec);
  });

  document.getElementById("backToEditBtn").addEventListener("click", () => {
    switchView("new");
  });

  document.getElementById("printBtn").addEventListener("click", () => {
    window.print();
  });

  document.getElementById("downloadPdfBtn").addEventListener("click", () => {
    if (!currentRenderedRecord) return;
    downloadPrescriptionPdf(currentRenderedRecord);
  });

  document.getElementById("emailBtn").addEventListener("click", () => {
    if (!currentRenderedRecord) return;
    sendPrescriptionEmail(currentRenderedRecord);
  });

  document.getElementById("deleteFromPreviewBtn").addEventListener("click", () => {
    if (!currentRecordId) return;
    if (confirm("Delete this prescription from history? This cannot be undone.")) {
      const remaining = getAllRecords().filter(r => r.id !== currentRecordId);
      saveAllRecords(remaining);
      showToast("Prescription deleted.");
      resetForm();
      switchView("history");
    }
  });

  document.getElementById("historySearch").addEventListener("input", (e) => {
    renderHistory(e.target.value);
  });

  document.getElementById("historySearchClear").addEventListener("click", () => {
    document.getElementById("historySearch").value = "";
    renderHistory("");
  });

  document.getElementById("letterheadTopMM").addEventListener("input", (e) => {
    const mm = parseInt(e.target.value, 10);
    if (!isNaN(mm)) setLetterheadTopMM(mm);
  });
}

/* ---------------- init ---------------- */

function init() {
  if (typeof initMedicineAutocomplete === "function") {
    initMedicineAutocomplete();
  }
  if (typeof initTestAutocomplete === "function") {
    initTestAutocomplete();
  }
  renderDoctorSelect();
  document.getElementById("pDate").value = todayISO();
  document.getElementById("dFollowup").min = todayISO();
  document.getElementById("letterheadTopMM").value = getLetterheadTopMM();
  addMedRow();
  wireEvents();
}

document.addEventListener("DOMContentLoaded", init);
